  -- ART
  ('e1000000-0000-4000-8000-000000000001', null, 'Springer Opera House', 'The State Theatre of Georgia and a National Historic Landmark in Columbus, where volunteers usher, give tours as docents, and help in the scene and costume shops.', 'https://www.springeroperahouse.org', 'https://www.google.com/s2/favicons?domain=www.springeroperahouse.org&sz=128', 'art', array['recurring', 'creative work'], false, false, 16, 'United States', 'GA', 'Columbus', true, true, 'both', false),
