insert into public.opportunities
  (id, org_id, title, category, description, tags, min_age, remote, is_online, is_ongoing,
   hours_estimate, signup_link, external_url, starts_at, city, state)
values
  ('e2000000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000001', 'Usher or Give Tours at the Springer', 'art', 'Volunteers usher at performances, give docent tours of this National Historic Landmark, or help in the scene and costume shops at the Springer Opera House in Columbus. There is a role whether you love being out front or working backstage. Applications are accepted year-round.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://www.springeroperahouse.org/volunteer', 'https://www.springeroperahouse.org/volunteer', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e2000000-0000-4000-8000-000000000002', 'e1000000-0000-4000-8000-000000000002', 'Work Front of House at the Grand', 'art', 'Volunteers run concessions and usher (and see productions free), or help build sets, paint, and run backstage crew at The Grand Opera House in Macon. It is a fun way to be part of a historic theater. Roles range from single shows to a regular schedule.', array['recurring', 'creative work'], 16, false, false, true, '3-4 hrs', 'https://thegrandoperahouse.com/get-involved/volunteer/', 'https://thegrandoperahouse.com/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Macon', 'GA'),
  ('e2000000-0000-4000-8000-000000000003', 'e1000000-0000-4000-8000-000000000003', 'Usher at Georgia Ensemble Theatre', 'art', 'Volunteers help seat patrons, answer questions, and tidy up after shows at Georgia Ensemble Theatre in Roswell, arriving about an hour before curtain and seeing the show for free. It is a great fit if you love live theater. Fill out the form to be added to the usher list.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://get.org/support-get/volunteer/', 'https://get.org/support-get/volunteer/', '2026-01-01T00:00:00Z', 'Roswell', 'GA'),
  ('e2000000-0000-4000-8000-000000000004', 'e1000000-0000-4000-8000-000000000004', 'Usher or Plan Events at Actor''s Express', 'art', 'Volunteers usher and see shows free, or serve on committees planning events, audience engagement, and fundraising at Actor''s Express in Atlanta. It is a welcoming way to be part of the theater community. Email the theater to get started.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://actors-express.com/get-involved/', 'https://actors-express.com/get-involved/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000005', 'e1000000-0000-4000-8000-000000000005', 'Lend Your Skills at 7 Stages', 'art', 'Volunteers contribute skills like set construction, graphic design, or data management, or become Community Ambassadors, at 7 Stages Theatre in Little Five Points. It is a good fit if you want to support bold, socially engaged theater. Reach out to be matched with a role.', array['recurring', 'creative work'], 16, false, false, true, 'Varies', 'https://www.7stages.org/get-involved/volunteer/', 'https://www.7stages.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000006', 'e1000000-0000-4000-8000-000000000006', 'Help Backstage at a Kids Theater', 'art', 'Volunteers help offstage with production tasks, organization, and promoting shows at Savannah Children''s Theatre, which needs help with graphic design and distributing fliers. It is a fun, creative way to support young performers. Roles are available year-round.', array['recurring', 'creative work', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.savannahchildrenstheatre.org/volunteer', 'https://www.savannahchildrenstheatre.org/volunteer', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000007', 'e1000000-0000-4000-8000-000000000007', 'Steward the Land at Hambidge', 'art', 'Volunteers help with trail maintenance, tree and shrub planting, invasive-species control, and habitat care across the 600-acre Hambidge Center in the north Georgia mountains. It is satisfying outdoor work in a beautiful creative community. Great for individuals and groups.', array['outdoors', 'physical work', 'good for crews'], 16, false, false, true, '2-4 hrs', 'https://www.hambidge.org/employment', 'https://www.hambidge.org/employment', '2026-01-01T00:00:00Z', 'Rabun Gap', 'GA'),
  ('e2000000-0000-4000-8000-000000000008', 'e1000000-0000-4000-8000-000000000008', 'Usher at the Rialto', 'art', 'Volunteers serve as ushers and ambassadors at the Rialto Center for the Arts at Georgia State, taking tickets, seating patrons, and helping run front of house after a short orientation. It is a great way to enjoy world-class performances while you help. Sign up through their volunteer form.', array['recurring', 'creative work'], 18, false, false, true, '3-4 hrs', 'https://rialto.gsu.edu/volunteer/', 'https://rialto.gsu.edu/volunteer/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000009', 'e1000000-0000-4000-8000-000000000009', 'Support a Gwinnett Ballet Production', 'art', 'Volunteers help with performances, outreach, and education at Gwinnett Ballet Theatre, the county''s first performing-arts nonprofit. If you love dance and the arts, it is a rewarding way to help. Roles are mostly production- and event-based.', array['recurring', 'creative work'], 14, false, false, true, '2-3 hrs', 'https://gwinnettballet.org/', 'https://gwinnettballet.org/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('e2000000-0000-4000-8000-000000000010', 'e1000000-0000-4000-8000-000000000010', 'Help Preserve Historic Savannah', 'art', 'Volunteers support programs, historic-property cleanups, office work, and special events with the Historic Savannah Foundation, which protects the city''s celebrated architecture. It is a great fit if you love history and preservation. Roles range from one-time events to ongoing help.', array['recurring', 'leadership role'], 16, false, false, true, '2-4 hrs', 'https://www.myhsf.org/support/volunteer/', 'https://www.myhsf.org/support/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000011', 'e1000000-0000-4000-8000-000000000011', 'Help at the Laney Museum', 'art', 'Volunteers assist staff during special programs, help with exhibitions, and support office work at the Lucy Craft Laney Museum of Black History in Augusta. It is a meaningful fit if you care about African American history and culture. Contact the museum to get involved.', array['recurring', 'leadership role'], 16, false, false, true, '2-3 hrs', 'https://lucycraftlaneymuseum.com/support/', 'https://lucycraftlaneymuseum.com/support/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('e2000000-0000-4000-8000-000000000012', 'e1000000-0000-4000-8000-000000000012', 'Be a Columbus Symphony Ambassador', 'music', 'Volunteers serve as ambassadors at concerts and events for the Columbus Symphony Orchestra, and can join the Friends of the Columbus Symphony supporting youth education and fundraising. Volunteers enjoy perks like free concert admission. It is a great fit for music lovers.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://csoga.org/support/volunteer-organizations/', 'https://csoga.org/support/volunteer-organizations/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e2000000-0000-4000-8000-000000000013', 'e1000000-0000-4000-8000-000000000013', 'Usher at the Albany Symphony', 'music', 'Volunteers serve as ushers, greeters, ticket takers, and event planners for the Albany Symphony Orchestra, southwest Georgia''s professional symphony. It is a rewarding way to enjoy and support live orchestral music. Reach out through the site to help.', array['recurring', 'creative work'], 16, false, false, true, '3 hrs', 'https://www.albanysymphony.org/volunteer', 'https://www.albanysymphony.org/volunteer', '2026-01-01T00:00:00Z', 'Albany', 'GA'),
  ('e2000000-0000-4000-8000-000000000014', 'e1000000-0000-4000-8000-000000000014', 'Support a Youth Orchestra', 'music', 'Volunteers help at rehearsals, concerts, and events for the Metropolitan Youth Symphony Orchestras of Atlanta, which furthers the music education of its students. It is a family-friendly way to support young musicians. Reach out through the site to find a role.', array['recurring', 'creative work', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://www.mysoatlanta.org/', 'https://www.mysoatlanta.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000015', 'e1000000-0000-4000-8000-000000000015', 'Build Homes in Columbus', 'faith', 'Volunteers help build affordable homes or work at the ReStore with Columbus Area Habitat for Humanity; volunteers must be at least 16 (or have a waiver), with a typical week of Tuesday through Saturday. It is rewarding, team-based work. No experience needed on build days.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.columbusareahabitat.com/volunteer', 'https://www.columbusareahabitat.com/volunteer', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e2000000-0000-4000-8000-000000000016', 'e1000000-0000-4000-8000-000000000016', 'Volunteer with Troup County Habitat', 'faith', 'Volunteers greet customers at the ReStore, help at community events, spread the word on social media, or work on home builds with Habitat for Humanity Troup County in LaGrange. Every role plays a part in the mission. It is a welcoming place to give your time.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.hfhtroup.org/volunteer-program', 'https://www.hfhtroup.org/volunteer-program', '2026-01-01T00:00:00Z', 'LaGrange', 'GA'),
  ('e2000000-0000-4000-8000-000000000017', 'e1000000-0000-4000-8000-000000000017', 'Build with Valdosta-Lowndes Habitat', 'faith', 'Volunteers help build affordable homes or work at the ReStore with Valdosta-Lowndes County Habitat for Humanity in south Georgia. Both skilled and unskilled hands are welcome, with tools and guidance provided on site. It is meaningful, hands-on work with a lasting result.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://www.valdostahabitat.org/', 'https://www.valdostahabitat.org/', '2026-01-01T00:00:00Z', 'Valdosta', 'GA'),
  ('e2000000-0000-4000-8000-000000000018', 'e1000000-0000-4000-8000-000000000018', 'Build Homes in Gwinnett', 'faith', 'Volunteers help build affordable homes for income-eligible families with Gwinnett Habitat for Humanity, working alongside future homeowners. No experience is needed on build days. It is a great group project that leaves something lasting behind.', array['good for crews', 'physical work', 'outdoors'], 16, false, false, true, 'Full day', 'https://habitatgwinnett.org/', 'https://habitatgwinnett.org/', '2026-01-01T00:00:00Z', 'Lawrenceville', 'GA'),
  ('e2000000-0000-4000-8000-000000000019', 'e1000000-0000-4000-8000-000000000019', 'Serve Meals at the Bread of Life Diner', 'faith', 'Volunteers prepare meals, serve diners, and help with cleanup at the Bread of Life Diner and other programs of Providence Ministries, a Christ-centered rescue mission in Dalton. There are roles for individuals and groups. It is a welcoming place to help neighbors in need.', array['good for crews', 'recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.providenceministriesinc.com/', 'https://www.providenceministriesinc.com/', '2026-01-01T00:00:00Z', 'Dalton', 'GA'),
  ('e2000000-0000-4000-8000-000000000020', 'e1000000-0000-4000-8000-000000000020', 'Serve a Meal at the Shelter', 'faith', 'Volunteers help prepare and serve breakfast, lunch, or dinner at The Salvation Army of Savannah''s emergency shelter, or assist with office and front-desk tasks. There are roles for individuals and groups. It is a flexible way to help neighbors experiencing homelessness on the coast.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://southernusa.salvationarmy.org/savannah/volunteer/', 'https://southernusa.salvationarmy.org/savannah/volunteer/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000021', 'e1000000-0000-4000-8000-000000000021', 'Foster and Care for Rescue Animals', 'animals', 'Volunteers foster animals, clean kennels, feed and bathe dogs, socialize pets, and help at adoption events with Georgia Animal Rescue & Defence, a no-kill shelter in southeast Georgia. There are roles for many interests and schedules. It is a great fit if you love animals.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://www.gardonline.org/volunteer/', 'https://www.gardonline.org/volunteer/', '2026-01-01T00:00:00Z', 'Pembroke', 'GA'),
  ('e2000000-0000-4000-8000-000000000022', 'e1000000-0000-4000-8000-000000000022', 'Care for Shelter Animals in Monroe', 'animals', 'Volunteers care for animals, help with adoptions, and support the community cat program at the Humane Society of Walton County, a no-kill shelter in Monroe. There are hands-on roles for animal lovers. Reach out through the site to get started.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://humanewalton.org/', 'https://humanewalton.org/', '2026-01-01T00:00:00Z', 'Monroe', 'GA'),
  ('e2000000-0000-4000-8000-000000000023', 'e1000000-0000-4000-8000-000000000023', 'Help Animals in Gainesville', 'animals', 'Volunteers walk dogs, comfort cats, and help with adoptions and events at the Humane Society of Northeast Georgia in Gainesville. There are roles for teens and adults. It is a rewarding way to help animals find homes in north Georgia.', array['recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://humanesocietyofnortheastgeorgia.org/', 'https://humanesocietyofnortheastgeorgia.org/', '2026-01-01T00:00:00Z', 'Gainesville', 'GA'),
  ('e2000000-0000-4000-8000-000000000024', 'e1000000-0000-4000-8000-000000000024', 'Foster a Dog in Athens', 'animals', 'Volunteers foster dogs, help with transport, and support adoption events with Athens Canine Rescue, a volunteer-driven, foster-based rescue. Fostering is the biggest need and a great option if your household can host a dog. Start through the site to learn more.', array['recurring', 'family friendly'], 16, false, false, true, 'Varies', 'https://athenscaninerescue.com/', 'https://athenscaninerescue.com/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e2000000-0000-4000-8000-000000000025', 'e1000000-0000-4000-8000-000000000025', 'Volunteer at Paws Humane', 'animals', 'Volunteers help care for animals, support adoption and spay/neuter services, and assist with pet-assisted therapy at Paws Humane Society in Columbus. Sign up through their volunteer portal. It is a great fit if you love animals and want a flexible role.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://pawshumane.org/', 'https://pawshumane.org/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e2000000-0000-4000-8000-000000000026', 'e1000000-0000-4000-8000-000000000026', 'Volunteer at Kennestone Hospital', 'medicine', 'Volunteers help with wayfinding, the gift shop, patient transport, activities, and pet and music therapy at Wellstar Kennestone in Marietta, where 400-plus volunteers serve each year. There are adult, college, and teen programs. It is a strong fit if you are exploring a health career.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.wellstar.org/community/volunteer/kennestone-hospital', 'https://www.wellstar.org/community/volunteer/kennestone-hospital', '2026-01-01T00:00:00Z', 'Marietta', 'GA'),
  ('e2000000-0000-4000-8000-000000000027', 'e1000000-0000-4000-8000-000000000027', 'Support Patients at Northside', 'medicine', 'Volunteers help with newborn photos, the gift shop, patient transport, and information desks through the Northside Hospital Atlanta Auxiliary. Volunteers commit to a weekly four-hour shift for at least a year. It is a great fit if you are interested in health care.', array['recurring', 'counts for school hours'], 16, false, false, true, '4 hrs / week', 'https://www.northsideatlaux.org/', 'https://www.northsideatlaux.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000028', 'e1000000-0000-4000-8000-000000000028', 'Volunteer at a Tanner Hospital', 'medicine', 'Volunteers brighten patients'' days at info desks, gift shops, and transport across Tanner Health''s west Georgia hospital campuses, plus hospice and pastoral care. There are roles for adults, students, and groups. It is a great fit if you are exploring health care in west Georgia.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.tanner.org/support-tanner/volunteer-at-a-tanner-hospital', 'https://www.tanner.org/support-tanner/volunteer-at-a-tanner-hospital', '2026-01-01T00:00:00Z', 'Carrollton', 'GA'),
  ('e2000000-0000-4000-8000-000000000029', 'e1000000-0000-4000-8000-000000000029', 'Volunteer on the Coast', 'medicine', 'Volunteers serve across Southeast Georgia Health System''s Brunswick and Camden hospital campuses, senior care centers, and community clinics. More than 300 people volunteer here. It is a strong option if you are interested in health care in coastal Georgia.', array['recurring', 'counts for school hours'], 16, false, false, true, '3-4 hrs / week', 'https://www.sghs.org/about-us/volunteer/', 'https://www.sghs.org/about-us/volunteer/', '2026-01-01T00:00:00Z', 'Brunswick', 'GA'),
  ('e2000000-0000-4000-8000-000000000030', 'e1000000-0000-4000-8000-000000000030', 'Volunteer at Colquitt Regional', 'medicine', 'Volunteers support patients, families, and staff at Colquitt Regional Medical Center in Moultrie, where volunteer services have served for nearly 60 years. Volunteers give hundreds of hours a year. It is a welcoming way to give back in south Georgia.', array['recurring'], 16, false, false, true, '3-4 hrs / week', 'https://colquittregional.com/about-us/volunteer-services/', 'https://colquittregional.com/about-us/volunteer-services/', '2026-01-01T00:00:00Z', 'Moultrie', 'GA'),
  ('e2000000-0000-4000-8000-000000000031', 'e1000000-0000-4000-8000-000000000031', 'Serve Families Facing Childhood Cancer', 'medicine', 'Volunteers 18 and up serve meals to families at pediatric cancer centers and help in the office with CURE Childhood Cancer, an Atlanta nonprofit funding research and supporting families. Cooking or serving a meal is a favorite group project. It is a direct way to comfort families in a hard season.', array['recurring', 'good for crews', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://curechildhoodcancer.org/volunteer-opportunities/', 'https://curechildhoodcancer.org/volunteer-opportunities/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000032', 'e1000000-0000-4000-8000-000000000032', 'Coach or Help at the Augusta Y', 'sports', 'Volunteers coach youth sports, support programs, and help at events with the Family YMCA of Greater Augusta. Volunteers complete an authorization form and background check first. It is a rewarding, recurring way to support youth and community wellness.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, '2-3 hrs / week', 'https://thefamilyy.org/about-us/volunteer/', 'https://thefamilyy.org/about-us/volunteer/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('e2000000-0000-4000-8000-000000000033', 'e1000000-0000-4000-8000-000000000033', 'Volunteer at the Columbus Y', 'sports', 'Volunteers coach youth sports, support aquatics and wellness programs, and mentor young people at the YMCA of Metropolitan Columbus. It is a great recurring role building character and community. Reach out to the Y to find a fit.', array['recurring', 'leadership role', 'family friendly'], 16, false, false, true, '2-3 hrs / week', 'https://www.ymcacolumbusga.com/', 'https://www.ymcacolumbusga.com/', '2026-01-01T00:00:00Z', 'Columbus', 'GA'),
  ('e2000000-0000-4000-8000-000000000034', 'e1000000-0000-4000-8000-000000000034', 'Pack Food in Statesboro', 'food', 'Volunteers manage inventory, organize donations, pack food for distribution, and help prepare community meals at the Statesboro Food Bank in Bulloch County. Groups from churches, clubs, and schools are welcome. It is a friendly, hands-on way to fight local hunger.', array['good for crews', 'recurring', 'family friendly'], 14, false, false, true, '2-3 hrs', 'https://statesborofoodbank.org/', 'https://statesborofoodbank.org/', '2026-01-01T00:00:00Z', 'Statesboro', 'GA'),
  ('e2000000-0000-4000-8000-000000000035', 'e1000000-0000-4000-8000-000000000035', 'Make Fresh Food Affordable', 'food', 'Volunteers help with events and programs at Wholesome Wave Georgia, which makes fresh, locally grown produce affordable for Georgians in need at farmers markets and beyond. Complete the volunteer survey to get connected. It is a good fit if you care about healthy food access.', array['recurring', 'good for crews'], 16, false, false, true, 'Varies', 'https://wholesomewavegeorgia.org/', 'https://wholesomewavegeorgia.org/', '2026-01-01T00:00:00Z', 'Atlanta', 'GA'),
  ('e2000000-0000-4000-8000-000000000036', 'e1000000-0000-4000-8000-000000000036', 'Lead Community Projects in Savannah', 'community', 'Volunteers advance women''s leadership and community impact through volunteer projects and training with the Junior League of Savannah. Membership is open to women 21 and up, with new classes each January and August. It is a great way to build leadership while serving the community.', array['recurring', 'leadership role'], 21, false, false, true, 'Varies', 'https://savannah.jl.org/community/', 'https://savannah.jl.org/community/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000037', 'e1000000-0000-4000-8000-000000000037', 'Welcome International Guests', 'community', 'Volunteers drive guests to Atlanta attractions, shop for groceries, care for the building and grounds, or host monthly community dinners at Villa International in Decatur, a home for visiting medical and scientific scholars. It is a warm way to build global friendships close to home.', array['recurring', 'family friendly'], 16, false, false, true, '2-3 hrs', 'https://villainternational.org/volunteer/', 'https://villainternational.org/volunteer/', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('e2000000-0000-4000-8000-000000000038', 'e1000000-0000-4000-8000-000000000038', 'Empower Refugee Women', 'community', 'Volunteers support economic empowerment, community health, and mentorship programs with the Refugee Women''s Network in Decatur, which equips refugee and immigrant women as leaders. Fill out the volunteer form to get involved. It is a meaningful way to support new Americans.', array['recurring', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://refugeewomensnetworkinc.org/volunteer', 'https://refugeewomensnetworkinc.org/volunteer', '2026-01-01T00:00:00Z', 'Decatur', 'GA'),
  ('e2000000-0000-4000-8000-000000000039', 'e1000000-0000-4000-8000-000000000039', 'Find a Project in the Augusta Area', 'community', 'United Way of the CSRA connects volunteers with vetted service projects and partner agencies across the Augusta and Central Savannah River Area. It is the easiest way to try different kinds of volunteering in the region. Great for individuals and groups.', array['good for crews', 'family friendly'], 16, false, false, true, 'Varies', 'https://www.uwcsra.org/volunteer', 'https://www.uwcsra.org/volunteer', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('e2000000-0000-4000-8000-000000000040', 'e1000000-0000-4000-8000-000000000040', 'Answer the Support Hotline', 'community', 'Volunteers train to staff the 24/7 support hotline at The Cottage in Athens, offering empathetic support to survivors of sexual violence and child abuse and connecting them to resources. Training is provided, and volunteers are 18 and up. It is a deeply meaningful role.', array['recurring', 'leadership role'], 18, false, false, true, 'Varies', 'https://www.northgeorgiacottage.org/volunteer', 'https://www.northgeorgiacottage.org/volunteer', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e2000000-0000-4000-8000-000000000041', 'e1000000-0000-4000-8000-000000000041', 'Support Survivors at Project Safe', 'community', 'Volunteers help at the thrift store, with lawn care and maintenance, and on projects supporting survivors of domestic violence and their children through Project Safe in Athens. Some roles ask for a year of commitment. It is a solid way to support survivors and prevention work.', array['recurring', 'good for crews'], 18, false, false, true, '2-3 hrs', 'https://project-safe.org/get-involved/volunteer-2/', 'https://project-safe.org/get-involved/volunteer-2/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e2000000-0000-4000-8000-000000000042', 'e1000000-0000-4000-8000-000000000042', 'Lead a Girl Scout Troop', 'education', 'Volunteers serve as troop leaders and mentors with Girl Scouts of Historic Georgia, delivering the Girl Scout experience to girls across 122 counties from the movement''s Savannah birthplace. No experience is required, and training is provided. It is a rewarding, recurring mentoring role.', array['recurring', 'leadership role', 'family friendly'], 18, false, false, true, '2-3 hrs / week', 'https://www.gshg.org/', 'https://www.gshg.org/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000043', 'e1000000-0000-4000-8000-000000000043', 'Help at Bethesda Academy', 'education', 'Volunteers help with events, fundraisers, and activities that support young men at Bethesda Academy in Savannah, one of the oldest child-serving institutions in the country. There are roles for individuals and groups. It is a meaningful way to support students on a historic campus.', array['recurring', 'counts for school hours'], 16, false, false, true, '2-3 hrs', 'https://www.bethesdaacademy.org/giving/volunteering/', 'https://www.bethesdaacademy.org/giving/volunteering/', '2026-01-01T00:00:00Z', 'Savannah', 'GA'),
  ('e2000000-0000-4000-8000-000000000044', 'e1000000-0000-4000-8000-000000000044', 'Monitor the St. Marys River', 'environment', 'Volunteers become citizen scientists monitoring water quality and join cleanups protecting the St. Marys River watershed with St. Marys Riverkeeper. It is hands-on outdoor conservation you can do close to home. Reach out through the site to get trained.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-3 hrs', 'https://www.stmarysriverkeeper.org/', 'https://www.stmarysriverkeeper.org/', '2026-01-01T00:00:00Z', 'St. Marys', 'GA'),
  ('e2000000-0000-4000-8000-000000000045', 'e1000000-0000-4000-8000-000000000045', 'Adopt a Stream Statewide', 'environment', 'Volunteers get trained through Georgia River Network to monitor water quality and organize to protect rivers from the mountains to the coast. It is a flexible, recurring role you can do near home. Great for a school project or a small crew.', array['outdoors', 'recurring', 'counts for school hours'], 14, false, false, true, '1-2 hrs / month', 'https://garivers.org/', 'https://garivers.org/', '2026-01-01T00:00:00Z', 'Athens', 'GA'),
  ('e2000000-0000-4000-8000-000000000046', 'e1000000-0000-4000-8000-000000000046', 'Join the Satilla River Cleanup', 'environment', 'Volunteers join the annual river-wide cleanup and other events protecting the Satilla River with Satilla Riverkeeper, pulling trash from the banks at public landings. Individuals, schools, and groups are all welcome. It is an easy, high-impact day outdoors.', array['outdoors', 'physical work', 'good for crews'], 12, false, false, true, '2-4 hrs', 'https://www.satillariverkeeper.org/', 'https://www.satillariverkeeper.org/', '2026-01-01T00:00:00Z', 'Woodbine', 'GA'),
  ('e2000000-0000-4000-8000-000000000047', 'e1000000-0000-4000-8000-000000000047', 'Plant Native Coastal Habitat', 'environment', 'Volunteers help with native-plant gardens, plant sales, and habitat stewardship events with Coastal WildScapes in Darien. It is a great way to learn about native plants while protecting coastal Georgia habitats. Roles are welcoming to first-timers.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.coastalwildscapes.org/', 'https://www.coastalwildscapes.org/', '2026-01-01T00:00:00Z', 'Darien', 'GA'),
  ('e2000000-0000-4000-8000-000000000048', 'e1000000-0000-4000-8000-000000000048', 'Work a Cooperative Farm', 'gardening', 'Volunteers help with planting, weeding, harvesting, and farm tasks at Love is Love Cooperative Farm, a worker-owned organic farm in Mansfield supplying metro Atlanta. It is hands-on outdoor work for people who love growing food. Complete the form to say where you would like to help.', array['outdoors', 'physical work', 'good for crews'], 14, false, false, true, '2-3 hrs', 'https://www.loveislovefarm.com/volunteering', 'https://www.loveislovefarm.com/volunteering', '2026-01-01T00:00:00Z', 'Mansfield', 'GA'),
  ('e2000000-0000-4000-8000-000000000049', 'e1000000-0000-4000-8000-000000000049', 'Support Veteran Families in Augusta', 'veterans', 'Volunteers bring meals and snacks, help with housekeeping, and organize goods drives at the Fisher House on the VA Augusta campus, a home away from home for families of veterans in care. It is a meaningful, hands-on way to thank those who served and their families.', array['recurring', 'good for crews', 'family friendly'], 18, false, false, true, '2-3 hrs', 'https://www.fisherhouse.org/get-involved/volunteer/', 'https://www.fisherhouse.org/get-involved/volunteer/', '2026-01-01T00:00:00Z', 'Augusta', 'GA'),
  ('e2000000-0000-4000-8000-000000000050', 'e1000000-0000-4000-8000-000000000050', 'Deliver Meals to Seniors', 'seniors', 'Volunteers deliver meals, drop off groceries, or make friendly visits to help older adults live independently through Senior Connections in Chamblee, which prepares and delivers nearly 3,000 meals a day across metro Atlanta. A route takes about an hour and can be a regular commitment.', array['recurring', 'family friendly'], 16, false, false, true, '1 hr / route', 'https://senior-connect.org/', 'https://senior-connect.org/', '2026-01-01T00:00:00Z', 'Chamblee', 'GA')
on conflict (id) do nothing;
